"""Minimal stdlib-only Chrome DevTools Protocol driver (WebSocket client + helpers)."""
import socket, os, json, base64, struct, subprocess, time, urllib.request, sys, shutil

HEADLESS_SHELL = os.path.expanduser('~/Library/Caches/ms-playwright/chromium_headless_shell-1254/chrome-headless-shell-mac-arm64/chrome-headless-shell')
FULL_CHROME = os.path.expanduser('~/Library/Caches/ms-playwright/chromium-1254/chrome-mac-arm64/Google Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing')


class WS:
    def __init__(self, url, timeout=120):
        assert url.startswith('ws://'), url
        rest = url[5:]
        hostport, _, path = rest.partition('/')
        host, _, port = hostport.partition(':')
        self.sock = socket.create_connection((host, int(port)))
        self.sock.settimeout(timeout)
        key = base64.b64encode(os.urandom(16)).decode()
        req = ('GET /%s HTTP/1.1\r\nHost: %s\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n'
               'Sec-WebSocket-Key: %s\r\nSec-WebSocket-Version: 13\r\n\r\n' % (path, hostport, key))
        self.sock.sendall(req.encode())
        buf = b''
        while b'\r\n\r\n' not in buf:
            chunk = self.sock.recv(4096)
            if not chunk:
                raise IOError('handshake failed')
            buf += chunk
        head, _, rest = buf.partition(b'\r\n\r\n')
        if b' 101 ' not in head.split(b'\r\n')[0]:
            raise IOError('bad handshake: %r' % head)
        self.buf = bytearray(rest)

    def _read(self, n):
        while len(self.buf) < n:
            chunk = self.sock.recv(1 << 20)
            if not chunk:
                raise IOError('socket closed')
            self.buf += chunk
        out = bytes(self.buf[:n])
        del self.buf[:n]
        return out

    def _frame(self, op, data):
        hdr = bytearray([0x80 | op])
        n = len(data)
        if n < 126:
            hdr.append(0x80 | n)
        elif n < 65536:
            hdr.append(0x80 | 126); hdr += struct.pack('>H', n)
        else:
            hdr.append(0x80 | 127); hdr += struct.pack('>Q', n)
        mask = os.urandom(4)
        hdr += mask
        masked = bytes(b ^ mask[i & 3] for i, b in enumerate(data))
        self.sock.sendall(bytes(hdr) + masked)

    def send(self, text):
        self._frame(0x1, text.encode('utf-8'))

    def recv(self):
        msg = bytearray()
        while True:
            b0, b1 = self._read(2)
            fin = b0 & 0x80
            op = b0 & 0x0f
            n = b1 & 0x7f
            if n == 126:
                n = struct.unpack('>H', self._read(2))[0]
            elif n == 127:
                n = struct.unpack('>Q', self._read(8))[0]
            mask = self._read(4) if (b1 & 0x80) else None
            payload = self._read(n)
            if mask:
                payload = bytes(b ^ mask[i & 3] for i, b in enumerate(payload))
            if op == 0x8:
                raise IOError('ws closed by peer')
            if op == 0x9:
                self._frame(0xA, payload)
                continue
            if op == 0xA:
                continue
            msg += payload
            if fin:
                return msg.decode('utf-8')


class CDP:
    def __init__(self, ws):
        self.ws = ws
        self.id = 0
        self.events = []

    def call(self, method, params=None):
        self.id += 1
        mid = self.id
        self.ws.send(json.dumps({'id': mid, 'method': method, 'params': params or {}}))
        while True:
            m = json.loads(self.ws.recv())
            if m.get('id') == mid:
                if 'error' in m:
                    raise RuntimeError('%s failed: %s' % (method, m['error']))
                return m.get('result', {})
            self.events.append(m)

    def pump(self, seconds):
        """Collect events for a while."""
        end = time.time() + seconds
        old = self.ws.sock.gettimeout()
        try:
            while True:
                left = end - time.time()
                if left <= 0:
                    break
                self.ws.sock.settimeout(left)
                try:
                    m = json.loads(self.ws.recv())
                except socket.timeout:
                    break
                self.events.append(m)
        finally:
            self.ws.sock.settimeout(old)

    def wait_event(self, name, timeout=60):
        end = time.time() + timeout
        idx = 0
        while True:
            while idx < len(self.events):
                if self.events[idx].get('method') == name:
                    return self.events[idx]
                idx += 1
            if time.time() > end:
                raise TimeoutError('event %s not seen' % name)
            self.pump(0.1)

    def evaluate(self, expr, await_promise=False):
        r = self.call('Runtime.evaluate', {'expression': expr, 'returnByValue': True,
                                           'awaitPromise': await_promise, 'userGesture': True})
        if 'exceptionDetails' in r:
            raise RuntimeError('JS exception: %s' % json.dumps(r['exceptionDetails'])[:2000])
        return r.get('result', {}).get('value')

    def screenshot(self, path, clip=None, fmt='png', quality=None):
        params = {'format': fmt, 'captureBeyondViewport': False}
        if quality is not None:
            params['quality'] = quality
        if clip:
            params['clip'] = clip
        r = self.call('Page.captureScreenshot', params)
        with open(path, 'wb') as f:
            f.write(base64.b64decode(r['data']))

    def console_dump(self):
        out = []
        for e in self.events:
            m = e.get('method')
            if m == 'Runtime.consoleAPICalled':
                p = e['params']
                txt = ' '.join(str(a.get('value', a.get('description', ''))) for a in p.get('args', []))
                out.append('[console.%s] %s' % (p.get('type'), txt))
            elif m == 'Runtime.exceptionThrown':
                d = e['params']['exceptionDetails']
                desc = d.get('exception', {}).get('description', '')
                out.append('[exception] %s %s (line %s)' % (d.get('text'), desc, d.get('lineNumber')))
            elif m == 'Log.entryAdded':
                en = e['params']['entry']
                out.append('[log.%s] %s %s' % (en.get('level'), en.get('text'), en.get('url', '')))
            elif m == 'Network.loadingFailed':
                out.append('[net.fail] %s' % json.dumps(e['params'])[:300])
        return out


class Browser:
    def __init__(self, width=1920, height=1080, port=9377, full=False, extra=None, udd=None, dpr=1):
        self.port = port
        self.udd = udd or os.path.join(os.environ.get('TMPDIR', '/tmp'), 'cdp-profile-%d' % port)
        shutil.rmtree(self.udd, ignore_errors=True)
        os.makedirs(self.udd, exist_ok=True)
        exe = FULL_CHROME if full else HEADLESS_SHELL
        args = [exe, '--remote-debugging-port=%d' % port, '--user-data-dir=' + self.udd,
                '--no-first-run', '--no-default-browser-check', '--hide-scrollbars', '--mute-audio',
                '--window-size=%d,%d' % (width, height), '--ignore-gpu-blocklist',
                '--allow-file-access-from-files', '--disable-background-timer-throttling',
                '--disable-renderer-backgrounding', '--disable-backgrounding-occluded-windows',
                '--force-device-scale-factor=%s' % dpr]
        if full:
            args.append('--headless=new')
        if extra:
            args += extra
        args.append('about:blank')
        self.proc = subprocess.Popen(args, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
        ws_url = None
        last = None
        for _ in range(100):
            time.sleep(0.15)
            try:
                with urllib.request.urlopen('http://127.0.0.1:%d/json/list' % port, timeout=2) as r:
                    targets = json.loads(r.read().decode())
                pages = [t for t in targets if t.get('type') == 'page']
                if pages:
                    ws_url = pages[0]['webSocketDebuggerUrl']
                    break
            except Exception as ex:  # noqa
                last = ex
                if self.proc.poll() is not None:
                    err = self.proc.stderr.read().decode('utf-8', 'replace')
                    raise RuntimeError('browser exited: %s' % err[-3000:])
        if not ws_url:
            raise RuntimeError('no devtools endpoint: %r' % (last,))
        self.cdp = CDP(WS(ws_url))
        c = self.cdp
        c.call('Page.enable'); c.call('Runtime.enable'); c.call('Log.enable'); c.call('Network.enable')
        c.call('Emulation.setDeviceMetricsOverride', {'width': width, 'height': height,
                                                      'deviceScaleFactor': dpr, 'mobile': False})

    def goto(self, url, settle=1.0):
        c = self.cdp
        c.events = []
        c.call('Page.navigate', {'url': url})
        c.wait_event('Page.loadEventFired', 90)
        c.pump(settle)

    def close(self):
        try:
            self.cdp.call('Browser.close')
        except Exception:
            pass
        try:
            self.proc.wait(timeout=5)
        except Exception:
            self.proc.kill()
        shutil.rmtree(self.udd, ignore_errors=True)

