/* brushed-metal streak map (roughness + bump), built from the seeded PRNG */
function brushedTexture() {
  const W = 256, H = 256, data = new Uint8Array(W * H * 4);
  const row = new Float32Array(W);
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) row[x] = rnd();
    const bias = rnd();
    for (let x = 0; x < W; x++) {
      let acc = 0;
      for (let k = -18; k <= 18; k++) acc += row[(x + k + W) % W];
      const v = clamp(0.5 + (acc / 37 - 0.5) * 4.2 + (bias - 0.5) * 0.4, 0, 1);
      const i = (y * W + x) * 4, b = Math.round(v * 255);
      data[i] = b; data[i + 1] = b; data[i + 2] = b; data[i + 3] = 255;
    }
  }
  const tex = new THREE.DataTexture(data, W, H, THREE.RGBAFormat);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.magFilter = THREE.LinearFilter;
  tex.minFilter = THREE.LinearMipmapLinearFilter;
  tex.generateMipmaps = true;
  tex.repeat.set(1.3, 5.0);
  tex.needsUpdate = true;
  return tex;
}

/* swept tube along the spine: the glass body (also reused by the frost shell) */
function buildDropGeometry() {
  const RS = 40, o = {};
  const ringS = [];
  let ell = 0;
  while (ell < SP.L - 1e-6) {
    const s = ell / SP.L;
    ringS.push(s);
    const w = spineAt(s, o).w;
    let step = 0.0125;
    if (w < 0.35) step = 0.0035 + 0.009 * (w / 0.35);
    else if (w > SPINE_W - 0.10) step = 0.005;
    ell += step;
  }
  ringS.push(1);
  const nr = ringS.length, nv = nr * (RS + 1);
  const pos = new Float32Array(nv * 3), nor = new Float32Array(nv * 3), srp = new Float32Array(nv * 3);
  const idx = new (nv > 65535 ? Uint32Array : Uint16Array)((nr - 1) * RS * 6);
  const rr = new Float64Array(nr);
  for (let k = 0; k < nr; k++) rr[k] = spineAt(ringS[k], o).r;
  rr[0] = 0; rr[nr - 1] = 0;
  let v = 0;
  for (let k = 0; k < nr; k++) {
    spineAt(ringS[k], o);
    const tl = Math.hypot(o.tx, o.ty, o.tz) || 1, tx = o.tx / tl, ty = o.ty / tl, tz = o.tz / tl;
    const k0 = Math.max(0, k - 1), k1 = Math.min(nr - 1, k + 1);
    const drdl = (rr[k1] - rr[k0]) / Math.max(1e-6, (ringS[k1] - ringS[k0]) * SP.L);
    const r = rr[k];
    for (let j = 0; j <= RS; j++, v++) {
      const phi = (j / RS) * Math.PI * 2, c = Math.cos(phi), sn = Math.sin(phi);
      const ex = c * o.nx + sn * o.bx, ey = c * o.ny + sn * o.by, ez = c * o.nz + sn * o.bz;
      const x = o.x + ex * r, y = o.y + ey * r, z = o.z + ez * r;
      let nx, ny, nz;
      if (o.w <= W_J) {                       // spherical head: exact normals
        nx = x - BULB.x; ny = y - BULB.y; nz = z - BULB.z;
        if (nx * nx + ny * ny + nz * nz < 1e-10) { nx = -tx; ny = -ty; nz = -tz; }
      } else {
        nx = ex - tx * drdl; ny = ey - ty * drdl; nz = ez - tz * drdl;
      }
      const nl = Math.hypot(nx, ny, nz) || 1;
      pos[v * 3] = x; pos[v * 3 + 1] = y; pos[v * 3 + 2] = z;
      nor[v * 3] = nx / nl; nor[v * 3 + 1] = ny / nl; nor[v * 3 + 2] = nz / nl;
      srp[v * 3] = ringS[k]; srp[v * 3 + 1] = r; srp[v * 3 + 2] = phi;
    }
  }
