  for (let k = 0; k < nr - 1; k++) {
    for (let j = 0; j < RS; j++) {
      const a = k * (RS + 1) + j, b = a + 1, c = a + RS + 2, d = a + RS + 1;
      idx[q++] = a; idx[q++] = b; idx[q++] = c; idx[q++] = a; idx[q++] = c; idx[q++] = d;
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
  g.setAttribute('aSRP', new THREE.BufferAttribute(srp, 3));
  g.setIndex(new THREE.BufferAttribute(idx, 1));
  return g;
}

/* one flat-shaded splinter: two apexes and a skewed triangular waist */
function needleGeometry() {
  const top = [0, 0.5, 0], bot = [0, -0.5, 0];
  const mid = [[0.5, 0.06, 0.0], [-0.27, -0.14, 0.43], [-0.23, 0.20, -0.44]];
  const pos = [], nor = [];
  const face = function (a, b, c) {
    const ux = b[0] - a[0], uy = b[1] - a[1], uz = b[2] - a[2];
    const vx = c[0] - a[0], vy = c[1] - a[1], vz = c[2] - a[2];
    let nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
    let p = [a, b, c];
    if (nx * (a[0] + b[0] + c[0]) + ny * (a[1] + b[1] + c[1]) + nz * (a[2] + b[2] + c[2]) < 0) {
      p = [a, c, b]; nx = -nx; ny = -ny; nz = -nz;
    }
    const l = Math.hypot(nx, ny, nz) || 1;
    for (let i = 0; i < 3; i++) { pos.push(p[i][0], p[i][1], p[i][2]); nor.push(nx / l, ny / l, nz / l); }
  };
  for (let k = 0; k < 3; k++) {
    const a = mid[k], b = mid[(k + 1) % 3];
    face(top, a, b);
    face(bot, b, a);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('normal', new THREE.Float32BufferAttribute(nor, 3));
  return g;
}

/* stratified sampling of s, weighted by a power of the local radius */
function spineSampler(power, floor) {
  const M = SP.n, cdf = new Float64Array(M + 1);
  let acc = 0;
  for (let i = 0; i <= M; i++) { acc += Math.pow(SP.rad[i], power) + floor; cdf[i] = acc; }
  let ci = 0;
  return function (i, n) {
    const target = (i + rnd()) / n * acc;
    while (ci < M && cdf[ci] < target) ci++;
    return clamp((ci - rnd()) / M, 0.0005, 0.9995);
  };
}
/* outward launch direction: spherical in the head, cylindrical along the tail */
function burstDir(o, px, py, pz, ex, ey, ez, out) {
  const head = 1 - smoothstep(W_J * 0.8, W_J * 1.5, o.w);
  let vx = ex, vy = ey, vz = ez;
  if (head > 0) {
    const hx = px - BULB.x, hy = py - BULB.y, hz = pz - BULB.z;
    const hl = Math.hypot(hx, hy, hz) || 1;
    vx = lerp(ex, hx / hl, head); vy = lerp(ey, hy / hl, head); vz = lerp(ez, hz / hl, head);
    const vl = Math.hypot(vx, vy, vz) || 1;
    vx /= vl; vy /= vl; vz /= vl;
  }
  out.x = vx; out.y = vy; out.z = vz;
  return head;
}

/* thousands of interlocking needles, pre-seeded inside the drop */
function buildShards(material) {
  const n = N_SHARD, o = {}, d3 = {}, bd = {};
  const pick = spineSampler(1.1, 0.012);
  const velBirth = new Float32Array(n * 4), spin = new Float32Array(n * 4), misc = new Float32Array(n * 4);
  const centres = new Float32Array(n * 3);
  const mesh = new THREE.InstancedMesh(needleGeometry(), material, n);
  const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), qr = new THREE.Quaternion();
  const p = new THREE.Vector3(), sc = new THREE.Vector3(), dir = new THREE.Vector3(), up = new THREE.Vector3(0, 1, 0);
  for (let i = 0; i < n; i++) {
    const s = pick(i, n);
    spineAt(s, o);
    const rel = Math.sqrt(clamp(o.r / RB, 0, 1));
    const headW = 1 - smoothstep(W_J * 0.8, W_J * 1.5, o.w);
    const len = (0.045 + 0.16 * Math.pow(rnd(), 2)) * (0.5 + 0.9 * rel);
    const wid = len * (0.07 + 0.11 * rnd());
    const phi = rnd() * Math.PI * 2, c = Math.cos(phi), sn = Math.sin(phi);
    const ex = c * o.nx + sn * o.bx, ey = c * o.ny + sn * o.by, ez = c * o.nz + sn * o.bz;
    rndUnit(d3);
    const a1 = (1 - 0.75 * headW) * (rnd() < 0.5 ? 1 : -1), a2 = 0.25 + 0.9 * headW * rnd();
    dir.set(o.tx * a1 + ex * a2 + d3.x * 0.35, o.ty * a1 + ey * a2 + d3.y * 0.35, o.tz * a1 + ez * a2 + d3.z * 0.35).normalize();
    const radial = Math.abs(dir.x * ex + dir.y * ey + dir.z * ez);
    const rho = Math.pow(rnd(), 0.45);
    const rr = Math.max(0, o.r - 0.5 * len * radial - 0.5 * wid) * rho;
    p.set(o.x + ex * rr, o.y + ey * rr, o.z + ez * rr);
    q.setFromUnitVectors(up, dir);
    qr.setFromAxisAngle(up, rnd() * Math.PI * 2);
    q.multiply(qr);
    sc.set(wid, len, wid * (0.4 + 0.6 * rnd()));
    m4.compose(p, q, sc);
    mesh.setMatrixAt(i, m4);
    burstDir(o, p.x, p.y, p.z, ex, ey, ez, bd);
    let speed = (0.45 + 2.9 * Math.pow(rnd(), 1.6)) * (0.42 + 1.05 * rel) * (0.45 + 0.55 * rho);
    if (s > S_CUT) speed *= 0.4;              // the severed tip crumbles inside the jaws
    const vt = (rnd() - 0.5) * 0.9 * (0.4 + rel);
    rndUnit(d3);
    velBirth[i * 4] = bd.x * speed + o.tx * vt + d3.x * 0.18;
    velBirth[i * 4 + 1] = bd.y * speed + o.ty * vt + d3.y * 0.18;
    velBirth[i * 4 + 2] = bd.z * speed + o.tz * vt + d3.z * 0.18;
    velBirth[i * 4 + 3] = fracTime(s) + rnd() * 0.035;
    rndUnit(d3);
    spin[i * 4] = d3.x; spin[i * 4 + 1] = d3.y; spin[i * 4 + 2] = d3.z;
    spin[i * 4 + 3] = (1.5 + 9 * rnd()) * (rnd() < 0.5 ? -1 : 1);
    misc[i * 4] = rnd(); misc[i * 4 + 1] = 1.3 + 1.7 * rnd(); misc[i * 4 + 2] = 0.55 + 0.9 * rnd(); misc[i * 4 + 3] = len;
    centres[i * 3] = p.x; centres[i * 3 + 1] = p.y; centres[i * 3 + 2] = p.z;
  }
  const g = mesh.geometry;
  g.setAttribute('aVelBirth', new THREE.InstancedBufferAttribute(velBirth, 4));
  g.setAttribute('aSpin', new THREE.InstancedBufferAttribute(spin, 4));
  g.setAttribute('aMisc', new THREE.InstancedBufferAttribute(misc, 4));
  mesh.instanceMatrix.needsUpdate = true;
  mesh.frustumCulled = false;
  return { mesh: mesh, velBirth: velBirth, misc: misc, centres: centres };
}

/* fine silica dust filling the same volume */
function buildDust(material) {
  const n = N_DUST, o = {}, d3 = {}, bd = {};
  const pick = spineSampler(1.25, 0.02);
  const pos = new Float32Array(n * 3), velBirth = new Float32Array(n * 4), misc = new Float32Array(n * 4);
  for (let i = 0; i < n; i++) {
    const s = pick(i, n);
    spineAt(s, o);
    const rel = Math.sqrt(clamp(o.r / RB, 0, 1));
    const phi = rnd() * Math.PI * 2, c = Math.cos(phi), sn = Math.sin(phi);
    const ex = c * o.nx + sn * o.bx, ey = c * o.ny + sn * o.by, ez = c * o.nz + sn * o.bz;
    const rr = o.r * Math.sqrt(rnd());
    const px = o.x + ex * rr, py = o.y + ey * rr, pz = o.z + ez * rr;
    burstDir(o, px, py, pz, ex, ey, ez, bd);
    let speed = (0.12 + 1.7 * Math.pow(rnd(), 2.2)) * (0.4 + 1.0 * rel);
    if (s > S_CUT) speed *= 0.4;
    const vt = (rnd() - 0.5) * 0.5 * (0.3 + rel);
    rndUnit(d3);
    pos[i * 3] = px; pos[i * 3 + 1] = py; pos[i * 3 + 2] = pz;
    velBirth[i * 4] = bd.x * speed + o.tx * vt + d3.x * 0.12;
    velBirth[i * 4 + 1] = bd.y * speed + o.ty * vt + d3.y * 0.12;
    velBirth[i * 4 + 2] = bd.z * speed + o.tz * vt + d3.z * 0.12;
    velBirth[i * 4 + 3] = fracTime(s) + rnd() * 0.06;
    misc[i * 4] = rnd(); misc[i * 4 + 1] = 2.2 + 2.6 * rnd(); misc[i * 4 + 2] = 0.22 + 0.5 * rnd();
    misc[i * 4 + 3] = 0.016 + 0.03 * Math.pow(rnd(), 2);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setAttribute('aVelBirth', new THREE.BufferAttribute(velBirth, 4));
  g.setAttribute('aMisc', new THREE.BufferAttribute(misc, 4));
  const pts = new THREE.Points(g, material);
  pts.frustumCulled = false;
  return pts;
}

/* sparkle sprites that ride on every Nth needle */
function buildGlints(shards, material) {
  const n = Math.floor(N_SHARD / N_GLINT_STEP);
  const pos = new Float32Array(n * 3), velBirth = new Float32Array(n * 4), misc = new Float32Array(n * 4);
  for (let k = 0; k < n; k++) {
    const i = k * N_GLINT_STEP;
    for (let c = 0; c < 3; c++) pos[k * 3 + c] = shards.centres[i * 3 + c];
    for (let c = 0; c < 4; c++) velBirth[k * 4 + c] = shards.velBirth[i * 4 + c];
    misc[k * 4] = rnd(); misc[k * 4 + 1] = shards.misc[i * 4 + 1]; misc[k * 4 + 2] = shards.misc[i * 4 + 2];
    misc[k * 4 + 3] = 0.16 + 0.22 * rnd();
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setAttribute('aVelBirth', new THREE.BufferAttribute(velBirth, 4));
  g.setAttribute('aMisc', new THREE.BufferAttribute(misc, 4));
  const pts = new THREE.Points(g, material);
  pts.frustumCulled = false;
  return pts;
}

