/* =====================================================================
 *  Lead bullet: analytic plastic mushrooming against the bulb
 * ===================================================================== */
const BUL = { L: 1.25, LN: 0.62, R: 0.24, BT: 0.14, LEAD: 0.70, V: 8.5, CMAX: 0.80, TDET: 0.72, SPIN: 9.0 };
const BN1 = 10, BN2 = 8, BN3 = 8, BN5 = 4, BNR = 44;
const BODY_A = (function () {                 // material stations along the shank (distance from the tip)
  const a = [];
  for (let i = 0; i <= 16; i++) a.push(BUL.LN * Math.pow(i / 16, 1.25));
  a.push(BUL.LEAD - 0.003, BUL.LEAD + 0.003, 0.80, 0.90, 1.0, BUL.L - BUL.BT, BUL.L - BUL.BT * 0.5, BUL.L - 0.02, BUL.L);
  return a;
})();
const BNP = BN1 + BN2 + BN3 + BODY_A.length + BN5;

function bulletR0(a) {                        // undeformed radius: conical nose, shank, boat tail
  if (a <= 0) return 0;
  if (a < BUL.LN) return BUL.R * (1 - Math.pow(1 - a / BUL.LN, 1.55));
  if (a < BUL.L - BUL.BT) return BUL.R + (a > BUL.LEAD ? 0.006 : 0);
  return (BUL.R + 0.006) * (1 - 0.13 * (a - (BUL.L - BUL.BT)) / BUL.BT);
}
function consumed(tau) {                      // length of nose already flattened (tau = time since impact)
  if (tau <= 0) return 0;
  const t0 = 2 * BUL.CMAX / BUL.V, x = 1 + Math.min(tau, BUL.TDET) / t0;
  return BUL.CMAX * (1 - 1 / (x * x));
}
function mushroomRadius(c) {
  return bulletR0(c) * (1 + 0.32 * smoothstep(0, 0.25, c)) + 0.16 * (1 - Math.exp(-c / 0.3));
}
function sphereDip(r) {                       // how far the bulb surface falls away from the contact plane
  const rc = Math.min(r, RB * 0.96);
  return -(RB - Math.sqrt(RB * RB - rc * rc));
}

function buildBullet(material) {
  const nv = BNP * (BNR + 1);
  const B = {
    lastC: -1,
    pos: new Float32Array(nv * 3), nor: new Float32Array(nv * 3), col: new Float32Array(nv * 3),
    prof: {
      r: new Float64Array(BNP), d: new Float64Array(BNP), x: new Float64Array(BNP), mat: new Float64Array(BNP),
      pet: new Float64Array(BNP), nx: new Float64Array(BNP), nr: new Float64Array(BNP), sph: new Uint8Array(BNP)
    }
  };
  const idx = new Uint16Array((BNP - 1) * BNR * 6);
  let q = 0;
  for (let k = 0; k < BNP - 1; k++) {
    for (let j = 0; j < BNR; j++) {
      const a = k * (BNR + 1) + j, b = a + 1, c = a + BNR + 2, d = a + BNR + 1;
      idx[q++] = a; idx[q++] = b; idx[q++] = c; idx[q++] = a; idx[q++] = c; idx[q++] = d;
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(B.pos, 3));
  g.setAttribute('normal', new THREE.BufferAttribute(B.nor, 3));
  g.setAttribute('color', new THREE.BufferAttribute(B.col, 3));
  g.setIndex(new THREE.BufferAttribute(idx, 1));
  B.mesh = new THREE.Mesh(g, material);
  B.mesh.rotation.order = 'ZYX';
  B.mesh.frustumCulled = false;
  setBulletShape(B, 0);
  return B;
}

/* lathe profile for a given consumed length c: glass-side face, rolled rim, cap back, shank, base */
function setBulletShape(B, c) {
  if (Math.abs(c - B.lastC) < 1e-7) return;
  B.lastC = c;
  const P = B.prof;
  const beta = 0.32 * smoothstep(0, 0.25, c);
  const rj = bulletR0(c) * (1 + beta);
  const Rm = mushroomRadius(c);
  const hr = 0.004 + 0.05 * smoothstep(0, 0.15, c);
  const hj = hr + 0.07 * smoothstep(0, 0.3, c);
  let k = 0;
  for (let i = 0; i < BN1; i++, k++) {
    const u = i / (BN1 - 1);
    P.r[k] = Rm * u; P.d[k] = 0; P.sph[k] = 1; P.mat[k] = -1; P.pet[k] = u;
  }
  for (let i = 0; i < BN2; i++, k++) {
    const a = Math.PI * (i + 1) / (BN2 + 1);
    P.r[k] = Rm + 0.45 * hr * Math.sin(a); P.d[k] = 0.5 * hr * (1 - Math.cos(a)); P.sph[k] = 1; P.mat[k] = -1; P.pet[k] = 1;
  }
