"""Screenshot the simulation at given simTimes by driving the real scrubber.
usage: shot.py --size 1920x1080 --times 0,1.3,4.6 --out PREFIX [--scale 0.5] [--clip x,y,w,h] [--settle 2.0]
"""
import sys, os, json, time, argparse
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from cdp import Browser

ap = argparse.ArgumentParser()
ap.add_argument('--size', default='1920x1080')
ap.add_argument('--times', default='0')
ap.add_argument('--out', required=True)
ap.add_argument('--scale', type=float, default=1.0)
ap.add_argument('--clip', default='')
ap.add_argument('--settle', type=float, default=2.5)
ap.add_argument('--port', type=int, default=9401)
ap.add_argument('--dpr', type=float, default=1)
ap.add_argument('--url', default='file:///private/tmp/pcd-sbx-claude-fable-5.2-dptq7qe0/work/index.html')
ap.add_argument('--js', default='')
a = ap.parse_args()

W, H = [int(v) for v in a.size.split('x')]
b = Browser(width=W, height=H, port=a.port, extra=['--no-sandbox'], dpr=a.dpr)
try:
    c = b.cdp
    t0 = time.time()
    b.goto(a.url, settle=a.settle)
    print('loaded in %.2fs (incl. settle %.1fs)' % (time.time() - t0, a.settle))
    for line in c.console_dump():
        print(line[:1500])
    info = c.evaluate("""(function(){
      var cv = document.getElementById('stage');
      return {three: typeof THREE, rev: (typeof THREE !== 'undefined') ? THREE.REVISION : null,
              cw: cv.width, ch: cv.height, cd: document.getElementById('countdown').textContent,
              disp: document.getElementById('countdown').style.display,
              scrub: document.getElementById('scrubber').value}; })()""")
    print('info', json.dumps(info))
    if a.js:
        print('js ->', json.dumps(c.evaluate(a.js, await_promise=True)))
    clip = None
    if a.clip:
        x, y, w, h = [float(v) for v in a.clip.split(',')]
        clip = {'x': x, 'y': y, 'width': w, 'height': h, 'scale': a.scale}
    elif a.scale != 1.0:
        clip = {'x': 0, 'y': 0, 'width': W, 'height': H, 'scale': a.scale}
    for ts in [s for s in a.times.split(',') if s.strip() != '']:
        t = float(ts)
        ms = c.evaluate("""(function(){
          var s = document.getElementById('scrubber');
          s.value = '%s';
          var t0 = performance.now();
          s.dispatchEvent(new Event('input', {bubbles: true}));
          var cv = document.getElementById('stage');
          var gl = cv.getContext('webgl2') || cv.getContext('webgl');
          if (gl) gl.finish();
          return performance.now() - t0; })()""" % ts)
        c.evaluate("new Promise(function(r){requestAnimationFrame(function(){requestAnimationFrame(function(){r(1);});});})", await_promise=True)
        path = '%s_%s.png' % (a.out, ('%.3f' % t).replace('.', 'p'))
        c.screenshot(path, clip=clip)
        print('t=%s render %.1f ms -> %s' % (ts, ms, path))
    c.pump(0.2)
    for line in c.console_dump():
        if 'console' in line or 'exception' in line or 'log.' in line:
            print('LATE', line[:1500])
finally:
    b.close()

