"""Frame pacing during real playback + countdown timeline, at a given viewport size."""
import sys, os, json, time
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from cdp import Browser

size = sys.argv[1] if len(sys.argv) > 1 else '1920x1080'
W, H = [int(v) for v in size.split('x')]
URL = 'file:///private/tmp/pcd-sbx-claude-fable-5.2-dptq7qe0/work/index.html'
PROBE = """(function(){
  window.__fr = []; window.__cd = [];
  var cd = document.getElementById('countdown'), sc = document.getElementById('scrubber');
  var last = null, lastTxt = null;
  function f(){
    var n = performance.now();
    var txt = cd.style.display === 'none' ? '(hidden)' : cd.textContent;
    if (txt !== lastTxt) { window.__cd.push([Math.round(n), txt]); lastTxt = txt; }
    if (last !== null) window.__fr.push([parseFloat(sc.value), n - last]);
    last = n;
    requestAnimationFrame(f);
  }
  requestAnimationFrame(f);
  return 1; })()"""

b = Browser(width=W, height=H, port=9421, extra=['--no-sandbox'])
try:
    c = b.cdp
    c.call('Page.addScriptToEvaluateOnNewDocument', {'source': "window.addEventListener('DOMContentLoaded', function(){ window.__t0 = performance.now(); }, true);"})
    c.events = []
    t0 = time.time()
    c.call('Page.navigate', {'url': URL})
    c.wait_event('Page.loadEventFired', 120)
    print('load event after %.2fs' % (time.time() - t0))
    c.evaluate(PROBE)
    c.pump(14.5)
    cd = c.evaluate('window.__cd')
    fr = c.evaluate('window.__fr')
    print('countdown transitions (ms since navigation start, text):', cd)
    if len(cd) >= 2:
        print('  digit durations (s):', ['%.2f' % ((cd[i + 1][0] - cd[i][0]) / 1000) for i in range(len(cd) - 1)])
    buckets = {}
    for st, dt in fr:
        k = int(st)
        buckets.setdefault(k, []).append(dt)
    print('simTime second -> frames, mean ms, max ms, fps')
    for k in sorted(buckets):
        v = buckets[k]
        print('  %d: n=%d mean=%.1f max=%.1f fps=%.1f' % (k, len(v), sum(v) / len(v), max(v), 1000.0 / (sum(v) / len(v))))
    for line in c.console_dump():
        if 'exception' in line or 'console.error' in line:
            print(line[:800])
finally:
    b.close()

