"""Per-object render cost at given simTimes, using a scratch copy of the page that exposes the scene bundle."""
import sys, os, json, time
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from cdp import Browser

SRC = '/private/tmp/pcd-sbx-claude-fable-5.2-dptq7qe0/work/index.html'
DST_DIR = '/private/tmp/pcd-sbx-claude-fable-5.2-dptq7qe0/tmp/prof'
os.makedirs(DST_DIR, exist_ok=True)
src = open(SRC, encoding='utf-8').read()
needle = '    fitCamera();\n    renderer.compile(scene, camera);'
assert src.count(needle) == 1
open(os.path.join(DST_DIR, 'index.html'), 'w', encoding='utf-8').write(src.replace(needle, '    window.__S = S;\n' + needle))

size = sys.argv[1] if len(sys.argv) > 1 else '1920x1080'
times = [float(v) for v in (sys.argv[2] if len(sys.argv) > 2 else '0.5,4.2,5.2,6.5').split(',')]
W, H = [int(v) for v in size.split('x')]
JS = """(function(t){
  var S = window.__S, gl = S.renderer.getContext(), px = new Uint8Array(4);
  var s = document.getElementById('scrubber'); s.value = String(t); s.dispatchEvent(new Event('input', {bubbles:true}));
  var objs = {glassBack:S.glassBack, glassFront:S.glassFront, frost:S.frost, shards:S.shards, dust:S.dust, lead:S.lead, glints:S.glints,
              nippers:S.nip.group, bullet:S.bullet.mesh, spall:S.spall.mesh, flash:S.flash, frontGlow:S.frontGlow, burst:S.burst, spark:S.spark};
  var clampRig = null; S.scene.children.forEach(function(c){ if (c.isGroup && c !== S.nip.group) clampRig = c; });
  objs.clamp = clampRig;
  var keep = {}; for (var k in objs) keep[k] = objs[k].visible;
  function run(){ var n = 3, t0 = performance.now(); for (var i=0;i<n;i++){ S.renderer.render(S.scene, S.camera); gl.readPixels(0,0,1,1,gl.RGBA,gl.UNSIGNED_BYTE,px); } return (performance.now()-t0)/n; }
  var out = {};
  out.all = run();
  for (var k in objs) objs[k].visible = false;
  out.none = run();
  for (var k in objs) { if (!keep[k]) continue; objs[k].visible = true; out[k] = run() - out.none; objs[k].visible = false; }
  for (var k in objs) objs[k].visible = keep[k];
  return out; })(%s)"""
b = Browser(width=W, height=H, port=9431, extra=['--no-sandbox'])
try:
    c = b.cdp
    b.goto('file://' + os.path.join(DST_DIR, 'index.html'), settle=4.0)
