p = '/private/tmp/pcd-sbx-claude-fable-5.2-dptq7qe0/work/index.html'
s = open(p, encoding='utf-8').read()


def rep(a, b, count=1):
    global s
    assert s.count(a) == count, 'count %d for %s' % (s.count(a), a[:70])
    s = s.replace(a, b)


# ---- needle geometry constants
a = s.index('  /* one splinter: two apexes and a skewed triangular waist')
b = s.index('  /* reorder per-item records so that index order == birth order')
s = s[:a] + '''  /* one splinter: two apexes and a skewed triangular waist (5 shared vertices, facets shaded flat) */
  const NEEDLE_V = [0, 0.5, 0, 0, -0.5, 0, 0.5, 0.06, 0.0, -0.27, -0.14, 0.43, -0.23, 0.20, -0.44];
  const NEEDLE_I = [0, 3, 2, 1, 2, 3, 0, 4, 3, 1, 3, 4, 0, 2, 4, 1, 4, 2];    // outward (CCW) faces
  function needleGeometry() {
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(NEEDLE_V, 3));
    g.setIndex(NEEDLE_I);
    return g;
  }

''' + s[b:]

# ---- shard builder
a = s.index('  /* thousands of interlocking needles, pre-seeded inside the drop */')
b = s.index('  /* fine silica dust filling the same volume */')
s = s[:a] + '''  /* Thousands of interlocking needles, pre-seeded inside the drop. Every HERO_STEP-th needle is a true GPU
     instance (THREE.InstancedMesh); the others are batched into a single mesh that stores the same per-needle
     launch parameters per vertex. Both are driven by the same analytic vertex shader. */
  const HERO_STEP = 6;
  function buildShards(heroMaterial, fieldMaterial) {
    const n = N_SHARD, o = {}, d3 = {}, bd = {};
    const pick = spineSampler(1.1, 0.012);
    const mats = new Float32Array(n * 16);
    const velBirth = new Float32Array(n * 4), spin = new Float32Array(n * 4), misc = new Float32Array(n * 4);
    const centres = new Float32Array(n * 3);
    const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), qr = new THREE.Quaternion();
    const p = new THREE.Vector3(), sc = new THREE.Vector3(), dir = new THREE.Vector3(), up = new THREE.Vector3(0, 1, 0);
    for (let i = 0; i < n; i++) {
      const s = pick(i, n);
      spineAt(s, o);
      const rel = Math.sqrt(clamp(o.r / RB, 0, 1));
      const headW = 1 - smoothstep(W_J * 0.8, W_J * 1.5, o.w);
      const len = (0.045 + 0.16 * Math.pow(rnd(), 2)) * (0.5 + 0.9 * rel);
      const wid = len * (0.07 + 0.11 * rnd());
      const phi = rnd() * Math.PI * 2, c = Math.cos(phi), sn = Math.sin(phi);
      const ex = c * o.nx + sn * o.bx, ey = c * o.ny + sn * o.by, ez = c * o.nz + sn * o.bz;
      rndUnit(d3);
      // needle axis: along the spine in the tail, radial in the head
      const a1 = (1 - 0.75 * headW) * (rnd() < 0.5 ? 1 : -1), a2 = 0.25 + 0.9 * headW * rnd();
      dir.set(o.tx * a1 + ex * a2 + d3.x * 0.35, o.ty * a1 + ey * a2 + d3.y * 0.35, o.tz * a1 + ez * a2 + d3.z * 0.35).normalize();
      const radial = Math.abs(dir.x * ex + dir.y * ey + dir.z * ez);
      const rho = Math.pow(rnd(), 0.45);
      const rr = Math.max(0, o.r - 0.5 * len * radial - 0.5 * wid) * rho;
      p.set(o.x + ex * rr, o.y + ey * rr, o.z + ez * rr);
      q.setFromUnitVectors(up, dir);
      qr.setFromAxisAngle(up, rnd() * Math.PI * 2);
      q.multiply(qr);
      sc.set(wid, len, wid * (0.4 + 0.6 * rnd()));
      m4.compose(p, q, sc);
      m4.toArray(mats, i * 16);
      burstDir(o, p.x, p.y, p.z, ex, ey, ez, bd);
      let speed = (0.45 + 2.9 * Math.pow(rnd(), 1.6)) * (0.40 + 1.9 * rel * rel) * (0.45 + 0.55 * rho);
      if (s > S_CUT) speed *= 0.4;              // the severed tip crumbles inside the jaws
      const vt = (rnd() - 0.5) * 0.9 * (0.4 + rel);
      rndUnit(d3);
      velBirth[i * 4] = bd.x * speed + o.tx * vt + d3.x * 0.18;
      velBirth[i * 4 + 1] = bd.y * speed + o.ty * vt + d3.y * 0.18;
      velBirth[i * 4 + 2] = bd.z * speed + o.tz * vt + d3.z * 0.18;
      velBirth[i * 4 + 3] = fracTime(s) + rnd() * 0.035;
      rndUnit(d3);
      spin[i * 4] = d3.x; spin[i * 4 + 1] = d3.y; spin[i * 4 + 2] = d3.z;
      spin[i * 4 + 3] = (1.5 + 9 * rnd()) * (rnd() < 0.5 ? -1 : 1);
      misc[i * 4] = rnd(); misc[i * 4 + 1] = 1.3 + 1.7 * rnd(); misc[i * 4 + 2] = 0.55 + 0.9 * rnd(); misc[i * 4 + 3] = len;
      centres[i * 3] = p.x; centres[i * 3 + 1] = p.y; centres[i * 3 + 2] = p.z;
    }

    // split into the two populations, each stored in birth order so only existing needles are drawn
    const byBirth = function (a, b) { return velBirth[a * 4 + 3] - velBirth[b * 4 + 3] || a - b; };
    const heroIdx = [], fieldIdx = [];
    for (let i = 0; i < n; i++) (i % HERO_STEP === 0 ? heroIdx : fieldIdx).push(i);
    heroIdx.sort(byBirth);
    fieldIdx.sort(byBirth);
    const gather = function (src, size, idx) {
      const out = new Float32Array(idx.length * size);
      for (let k = 0; k < idx.length; k++) for (let c = 0; c < size; c++) out[k * size + c] = src[idx[k] * size + c];
      return out;
    };

    const nh = heroIdx.length;
    const hero = new THREE.InstancedMesh(needleGeometry(), heroMaterial, nh);
    hero.instanceMatrix.array.set(gather(mats, 16, heroIdx));
    hero.instanceMatrix.needsUpdate = true;
    hero.geometry.setAttribute('aVelBirth', new THREE.InstancedBufferAttribute(gather(velBirth, 4, heroIdx), 4));
    hero.geometry.setAttribute('aSpin', new THREE.InstancedBufferAttribute(gather(spin, 4, heroIdx), 4));
    hero.geometry.setAttribute('aMisc', new THREE.InstancedBufferAttribute(gather(misc, 4, heroIdx), 4));
    hero.frustumCulled = false;
    const heroBirths = new Float32Array(nh);
    for (let k = 0; k < nh; k++) heroBirths[k] = velBirth[heroIdx[k] * 4 + 3];

    const nf = fieldIdx.length, NV = NEEDLE_V.length / 3, NI = NEEDLE_I.length;
    const fPos = new Float32Array(nf * NV * 3), fCen = new Float32Array(nf * NV * 3);
    const fVel = new Float32Array(nf * NV * 4), fSpin = new Float32Array(nf * NV * 4), fMisc = new Float32Array(nf * NV * 4);
    const fIdx = new (nf * NV > 65535 ? Uint32Array : Uint16Array)(nf * NI);
    const fieldBirths = new Float32Array(nf);
    for (let k = 0; k < nf; k++) {
      const i = fieldIdx[k], m = i * 16;
      fieldBirths[k] = velBirth[i * 4 + 3];
      for (let v = 0; v < NV; v++) {
        const x = NEEDLE_V[v * 3], y = NEEDLE_V[v * 3 + 1], z = NEEDLE_V[v * 3 + 2], w = k * NV + v;
        fPos[w * 3] = mats[m] * x + mats[m + 4] * y + mats[m + 8] * z;          // rest-pose offset from the centre
        fPos[w * 3 + 1] = mats[m + 1] * x + mats[m + 5] * y + mats[m + 9] * z;
        fPos[w * 3 + 2] = mats[m + 2] * x + mats[m + 6] * y + mats[m + 10] * z;
        for (let c = 0; c < 3; c++) fCen[w * 3 + c] = centres[i * 3 + c];
        for (let c = 0; c < 4; c++) {
          fVel[w * 4 + c] = velBirth[i * 4 + c]; fSpin[w * 4 + c] = spin[i * 4 + c]; fMisc[w * 4 + c] = misc[i * 4 + c];
        }
      }
      for (let t = 0; t < NI; t++) fIdx[k * NI + t] = k * NV + NEEDLE_I[t];
    }
    const fg = new THREE.BufferGeometry();
    fg.setAttribute('position', new THREE.BufferAttribute(fPos, 3));
    fg.setAttribute('aCentre', new THREE.BufferAttribute(fCen, 3));
    fg.setAttribute('aVelBirth', new THREE.BufferAttribute(fVel, 4));
    fg.setAttribute('aSpin', new THREE.BufferAttribute(fSpin, 4));
    fg.setAttribute('aMisc', new THREE.BufferAttribute(fMisc, 4));
    fg.setIndex(new THREE.BufferAttribute(fIdx, 1));
    const field = new THREE.Mesh(fg, fieldMaterial);
    field.frustumCulled = false;

    return {
      hero: hero, field: field, heroBirths: heroBirths, fieldBirths: fieldBirths,
      velBirth: velBirth, misc: misc, centres: centres
    };
  }

