# ---- glints: now sort by birth themselves
rep('''    const births = new Float32Array(n);
    for (let k = 0; k < n; k++) births[k] = velBirth[k * 4 + 3];
    const pts = new THREE.Points(g, material);
    pts.frustumCulled = false;
