rep('glassBack: glassBack, glassFront: glassFront, frost: frost, shards: shards.mesh, dust: dust, lead: lead, glints: glints,',
    'glassBack: glassBack, glassFront: glassFront, frost: frost, shards: shards.hero, shardField: shards.field,\n      heroBirths: shards.heroBirths, fieldBirths: shards.fieldBirths, dust: dust, lead: lead, glints: glints,')
rep('      shardBirths: shards.births, nip: nip, bullet: bullet, spall: spall,', '      nip: nip, bullet: bullet, spall: spall,')
