  /* studio light-box -> PMREM reflection map */
  function buildEnvironment(renderer) {
    const env = new THREE.Scene();
    const disposables = [];
    const add = function (geo, r, g, b, side) {
      const mat = new THREE.MeshBasicMaterial({ color: new THREE.Color(r, g, b), side: side });
      const m = new THREE.Mesh(geo, mat);
      disposables.push(geo, mat);
      env.add(m);
      return m;
    };
