const BUL = { L: 1.25, LN: 0.62, R: 0.24, BT: 0.14, LEAD: 0.70, V: 8.5, CMAX: 0.80, TDET: 0.72, SPIN: 9.0 };
const BN1 = 10, BN2 = 8, BN3 = 8, BN5 = 4, BNR = 44;
const BODY_A = (function () {                 // material stations along the shank (distance from the tip)
  const a = [];
  for (let i = 0; i <= 16; i++) a.push(BUL.LN * Math.pow(i / 16, 1.25));
  a.push(BUL.LEAD - 0.003, BUL.LEAD + 0.003, 0.80, 0.90, 1.0, BUL.L - BUL.BT, BUL.L - BUL.BT * 0.5, BUL.L - 0.02, BUL.L);
  return a;
})();
const BNP = BN1 + BN2 + BN3 + BODY_A.length + BN5;

function bulletR0(a) {                        // undeformed radius: conical nose, shank, boat tail
  if (a <= 0) return 0;
  if (a < BUL.LN) return BUL.R * (1 - Math.pow(1 - a / BUL.LN, 1.55));
  if (a < BUL.L - BUL.BT) return BUL.R + (a > BUL.LEAD ? 0.006 : 0);
  return (BUL.R + 0.006) * (1 - 0.13 * (a - (BUL.L - BUL.BT)) / BUL.BT);
}
function consumed(tau) {                      // length of nose already flattened (tau = time since impact)
  if (tau <= 0) return 0;
  const t0 = 2 * BUL.CMAX / BUL.V, x = 1 + Math.min(tau, BUL.TDET) / t0;
  return BUL.CMAX * (1 - 1 / (x * x));
