function mushroomRadius(c) {
  return bulletR0(c) * (1 + 0.32 * smoothstep(0, 0.25, c)) + 0.16 * (1 - Math.exp(-c / 0.3));
}
function sphereDip(r) {                       // how far the bulb surface falls away from the contact plane
  const rc = Math.min(r, RB * 0.96);
  return -(RB - Math.sqrt(RB * RB - rc * rc));
}

function buildBullet(material) {
  const nv = BNP * (BNR + 1);
  const B = {
    lastC: -1,
    pos: new Float32Array(nv * 3), nor: new Float32Array(nv * 3), col: new Float32Array(nv * 3),
    prof: {
      r: new Float64Array(BNP), d: new Float64Array(BNP), x: new Float64Array(BNP), mat: new Float64Array(BNP),
      pet: new Float64Array(BNP), nx: new Float64Array(BNP), nr: new Float64Array(BNP), sph: new Uint8Array(BNP)
    }
  };
  const idx = new Uint16Array((BNP - 1) * BNR * 6);
  let q = 0;
  for (let k = 0; k < BNP - 1; k++) {
    for (let j = 0; j < BNR; j++) {
      const a = k * (BNR + 1) + j, b = a + 1, c = a + BNR + 2, d = a + BNR + 1;
